journals.script:
{
is_shown_when_inactive = {
	has_variable = ywc_v03_initialized
	NOT = { has_variable = ywc_c07_started }
	OR = {
		ywc_c07_case_ready_local = yes
		var:ywc_c07_case_open ?= 1
	}
}
possible = {
	has_variable = ywc_v03_initialized
	ywc_v03_has_capacity = yes
	NOT = { has_variable = ywc_c07_started }
	OR = {
		ywc_c07_case_ready_local = yes
		var:ywc_c07_case_open ?= 1
	}
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c07_started } }
		set_variable = { name = ywc_c07_started value = 1 }
		set_variable = { name = ywc_c07_popup_epoch value = 0 }
		set_variable = { name = ywc_c07_wait_age value = 0 }
		change_variable = { name = ywc_v03_active_arc_count add = 1 }
		change_variable = { name = ywc_v03_visible_task_count add = 1 }
	}
	if = { limit = { NOT = { has_variable = ywc_c07_popup_epoch } } set_variable = { name = ywc_c07_popup_epoch value = 0 } }
	if = { limit = { ywc_c07_case_ready_local = yes NOT = { has_variable = ywc_c07_role } NOT = { has_variable = ywc_c07_case_open } }
		set_variable = { name = ywc_c07_role value = 1 }
		set_variable = { name = ywc_c07_case_open value = 1 }
		set_variable = { name = ywc_c07_stage value = 1600 }
		set_variable = { name = ywc_c07_pending value = 1600 }
	}
	if = { limit = { var:ywc_c07_case_open ?= 1 NOT = { has_variable = ywc_c07_role } } set_variable = { name = ywc_c07_role value = 2 } }
	if = { limit = { var:ywc_c07_role ?= 2 NOT = { has_variable = ywc_c07_stage } }
		set_variable = { name = ywc_c07_stage value = 1612 }
		set_variable = { name = ywc_c07_wait_age value = 0 }
	}
	if = { limit = { var:ywc_c07_role ?= 1 NOT = { has_variable = ywc_c07_funder_mounted } } ywc_c07_mount_funder = yes }
}
on_monthly_pulse = {
	effect = {
		if = { limit = { var:ywc_c07_role ?= 1 NOT = { has_variable = ywc_c07_funder_mounted } } ywc_c07_mount_funder = yes }
		if = { limit = { var:ywc_c07_role ?= 1 var:ywc_c07_stage ?= 1613 }
			change_variable = { name = ywc_c07_wait_age add = 1 }
			if = { limit = { OR = { ywc_c07_funder_resolved = yes ywc_c07_funder_gone = yes var:ywc_c07_wait_age >= 12 } } ywc_c07_after_guarantee = yes }
		}
		if = { limit = { var:ywc_c07_role ?= 2 var:ywc_c07_stage ?= 1612 }
			change_variable = { name = ywc_c07_wait_age add = 1 }
			if = { limit = { OR = { ywc_c07_host_gone = yes var:ywc_c07_wait_age >= 36 } } ywc_c07_close_no_talks = yes }
		}
		if = { limit = { var:ywc_c07_role ?= 2 var:ywc_c07_stage ?= 1602 ywc_c07_host_gone = yes } ywc_c07_close_status_quo = yes }
		if = { limit = { var:ywc_c07_role ?= 2 var:ywc_c07_stage ?= 1602 NOT = { has_variable = ywc_c07_pending } }
			change_variable = { name = ywc_c07_wait_age add = 1 }
			if = { limit = { var:ywc_c07_wait_age >= 36 } ywc_c07_close_status_quo = yes }
		}
		if = { limit = { ywc_c07_host_delivery_1600 = yes } trigger_event = { id = ywc_crisis.1600 } }
		if = { limit = { ywc_c07_host_delivery_1601 = yes } trigger_event = { id = ywc_crisis.1601 } }
		if = { limit = { ywc_c07_funder_delivery_1602 = yes } trigger_event = { id = ywc_crisis.1602 } }
		if = { limit = { ywc_c07_host_delivery_1603 = yes } trigger_event = { id = ywc_crisis.1603 } }
	}
}
}

{
is_shown_when_inactive = { has_variable = ywc_c07_execution_open }
possible = {
	has_variable = ywc_v03_initialized
	has_variable = ywc_c07_started
	var:ywc_c07_execution_open ?= 1
	ywc_c07_is_pool_tag = yes
	NOT = { has_variable = ywc_c07_outcome }
}
immediate = {
	if = { limit = { NOT = { has_variable = ywc_c07_popup_epoch } } set_variable = { name = ywc_c07_popup_epoch value = 0 } }
}
on_monthly_pulse = {
	effect = {
		if = { limit = { var:ywc_c07_role ?= 1 var:ywc_c07_stage ?= 1614 }
			change_variable = { name = ywc_c07_wait_age add = 1 }
			if = { limit = { OR = { ywc_c07_funder_rescheduled = yes ywc_c07_funder_gone = yes var:ywc_c07_wait_age >= 12 } } ywc_c07_open_conflict = yes }
		}
		if = { limit = { var:ywc_c07_role ?= 1 var:ywc_c07_stage ?= 1606 NOT = { ywc_c07_labor_risk = yes } } ywc_c07_open_tariff = yes }
		if = { limit = { var:ywc_c07_role ?= 1 var:ywc_c07_stage ?= 1616 }
			change_variable = { name = ywc_c07_wait_age add = 1 }
			if = { limit = { OR = { ywc_c07_funder_tariff_done = yes ywc_c07_funder_gone = yes var:ywc_c07_wait_age >= 12 } } ywc_c07_route_to_renegotiation = yes }
		}
		if = { limit = { var:ywc_c07_role ?= 2 var:ywc_c07_stage ?= 1615 }
			change_variable = { name = ywc_c07_wait_age add = 1 }
			if = { limit = { ywc_c07_host_gone = yes } ywc_c07_close_status_quo = yes }
			if = { limit = { var:ywc_c07_wait_age >= 24 } ywc_c07_funder_self_tariff = yes }
		}
		if = { limit = { var:ywc_c07_role ?= 2 var:ywc_c07_stage ?= 1617 }
			change_variable = { name = ywc_c07_wait_age add = 1 }
			if = { limit = { OR = { ywc_c07_host_gone = yes var:ywc_c07_wait_age >= 24 } } ywc_c07_close_status_quo = yes }
		}
		if = { limit = { var:ywc_c07_role ?= 2 var:ywc_c07_stage ?= 1605 ywc_c07_host_gone = yes } ywc_c07_close_status_quo = yes }
		if = { limit = { var:ywc_c07_role ?= 2 var:ywc_c07_stage ?= 1607 ywc_c07_host_gone = yes } ywc_c07_close_status_quo = yes }
		if = { limit = { ywc_c07_host_delivery_1604 = yes } trigger_event = { id = ywc_crisis.1604 } }
		if = { limit = { ywc_c07_funder_delivery_1605 = yes } trigger_event = { id = ywc_crisis.1605 } }
		if = { limit = { ywc_c07_host_delivery_1606 = yes } trigger_event = { id = ywc_crisis.1606 } }
		if = { limit = { ywc_c07_host_delivery_1607 = yes } trigger_event = { id = ywc_crisis.1607 } }
		if = { limit = { ywc_c07_funder_delivery_1607 = yes } trigger_event = { id = ywc_crisis.1607 } }
	}
}
}

